import type { Caption } from "@remotion/captions";

/**
 * An EditSpec fully describes one finished video. It is plain JSON so it can be
 * generated by scripts/plan.mjs, hand-edited, and passed to the renderer as
 * input props. All paths are relative to the `public/` folder.
 */

export type TransitionKind =
  | "none"
  | "fade"
  | "slide-left"
  | "slide-up"
  | "wipe"
  | "zoom-punch";

export type Segment = {
  /** Shown in Studio and QC reports. */
  name: string;
  kind: "video" | "image";
  /** Path inside public/, e.g. "media/sample/clip-1.mp4". */
  src: string;
  /** Pixel size of the source (filled in by ingest). Needed for exact crop maths. */
  srcWidth: number;
  srcHeight: number;
  /** Video only: where to start inside the source clip (seconds). */
  trimStartSec?: number;
  /** How long this segment lasts on the timeline (seconds, before transition overlap). */
  durationSec: number;
  /** Video only: 0.5 = half speed, 2 = double speed. */
  playbackRate?: number;
  /** Video only: 0..1. */
  volume?: number;
  /**
   * Crop focus for "cover" framing, 0..1 (0,0 = top-left). Lets a landscape
   * clip be cropped to 9:16 around the product instead of the centre.
   */
  focusX?: number;
  focusY?: number;
  /**
   * "cover" fills the 9:16 frame (crops). "contain" shows the whole frame
   * (used for product images so packaging is never cut off).
   */
  fit?: "cover" | "contain";
  /** Scale at the start and end of the segment. Clamped to maxZoom. */
  zoomFrom?: number;
  zoomTo?: number;
  /** Transition into this segment from the previous one. */
  transitionIn?: TransitionKind;
  /** Optional short label shown top-left (e.g. "Day 7", "Texture"). */
  label?: string;
  /** Seconds into the segment before the label appears (avoids overlapping the title card). */
  labelFromSec?: number;
};

export type CaptionStyle = "bold-pop" | "clean-box" | "karaoke";

export type ProductInfo = {
  name: string;
  shortName: string;
  price?: string;
  /** Hex colour sampled from the packaging. Used for accents only, never applied to the product. */
  brandColor: string;
  accentColor: string;
  benefits: string[];
  /** Product image inside public/ (PNG with transparency works best). */
  image?: string;
};

export type EditSpec = {
  /** e.g. "A - Hook & Fast Cuts" */
  editName: string;
  platform: "tiktok-shop" | "amazon-influencer" | "ugc";
  fps: number;
  width: number;
  height: number;
  product: ProductInfo;
  /** Big hook text shown at the very start. */
  hook: string;
  hookDurationSec: number;
  /** Call to action on the end card. */
  cta: string;
  endCardSec: number;
  transitionSec: number;
  /** Safety limit for zooms so the product is never blown up or distorted. */
  maxZoom: number;
  segments: Segment[];
  captionStyle: CaptionStyle;
  /** Times are in ms relative to the start of the video. */
  captions: Caption[];
  /** Optional: distance of captions from the bottom edge (px). Raise/lower to keep them off the product. */
  captionBottomPx?: number;
  /** Where the product title card appears. */
  titleCard: { startSec: number; durationSec: number };
  showPrice: boolean;
  showRating: boolean;
  music?: { src: string; volume: number };
};
